import wfdb, numpy as np, neurokit2 as nk, warnings, json, sys
warnings.filterwarnings('ignore')

def analyze(eid):
    r=wfdb.rdrecord('ecgall/'+eid)
    fs=r.fs; sig=r.p_signal; names=r.sig_name
    res={'ecg':eid}
    # R peaks from lead II (fallback V5, I)
    rpk=None
    for ln in ['II','V5','I','V2']:
        s=sig[:,names.index(ln)]
        s=np.nan_to_num(s)
        try:
            cl=nk.ecg_clean(s,sampling_rate=fs)
            pk=nk.ecg_peaks(cl,sampling_rate=fs)[1]['ECG_R_Peaks']
        except Exception:
            continue
        if len(pk)>=6:
            rpk=np.array(pk); lead=ln; break
    if rpk is None: return res
    rr=np.diff(rpk)/fs
    rr=rr[(rr>0.25)&(rr<2.5)]
    res['n_beats']=len(rpk); res['lead']=lead
    res['hr']=60/np.median(rr)
    res['hr_mean']=60*len(rr)/rr.sum()
    res['rr_cv']=float(np.std(rr)/np.mean(rr))
    res['rmssd']=float(np.sqrt(np.mean(np.diff(rr)**2))*1000) if len(rr)>2 else None
    res['pnn50']=float(np.mean(np.abs(np.diff(rr))>0.05)) if len(rr)>2 else None
    # QT per lead via delineation
    qts={}
    for ln in ['II','V5','V2','I','V4','aVL','V3','V6']:
        s=np.nan_to_num(sig[:,names.index(ln)])
        try:
            cl=nk.ecg_clean(s,sampling_rate=fs)
            _,w=nk.ecg_delineate(cl,rpeaks={'ECG_R_Peaks':rpk},sampling_rate=fs,method='dwt')
            on=np.array(w['ECG_R_Onsets'],dtype=float); toff=np.array(w['ECG_T_Offsets'],dtype=float)
            vals=[]
            for a,b in zip(on,toff):
                if np.isnan(a) or np.isnan(b): continue
                q=(b-a)/fs
                if 0.2<q<0.75: vals.append(q)
            if len(vals)>=3: qts[ln]=float(np.median(vals))
        except Exception:
            pass
    res['qt_leads']=qts
    if qts:
        res['qt']=float(np.median(list(qts.values())))
        res['qt_max']=float(max(qts.values()))
    # P wave presence
    pw={}
    for ln in ['II','V1','I']:
        s=np.nan_to_num(sig[:,names.index(ln)])
        try:
            cl=nk.ecg_clean(s,sampling_rate=fs)
            _,w=nk.ecg_delineate(cl,rpeaks={'ECG_R_Peaks':rpk},sampling_rate=fs,method='peak')
            pp=np.array(w['ECG_P_Peaks'],dtype=float)
            pw[ln]=float(np.mean(~np.isnan(pp)))
        except Exception:
            pass
    res['p_frac']=pw
    return res

if __name__=='__main__':
    ids=sys.argv[1:]
    out=[]
    for i in ids:
        try: out.append(analyze(i))
        except Exception as e: out.append({'ecg':i,'err':str(e)})
    print(json.dumps(out,indent=1,default=float))
